  xma10 Vhigh Vbias1 VDD VDD sky130_fd_pr__pfet_01v8 w={W_xma10} l={L_xma10}
  xma11 Vncas Vbias2 N008 VDD sky130_fd_pr__pfet_01v8 w={W_xma11} l={L_xma11}
  xma12 N008 Vbias1 VDD VDD sky130_fd_pr__pfet_01v8 w={W_xma12} l={L_xma12}
  xm16 Vncas Vncas N012 0 sky130_fd_pr__nfet_01v8 w={W_xm16} l={L_xm16}
  xm17 N012 Vbias3 P001 0 sky130_fd_pr__nfet_01v8 w={W_xm17} l={L_xm17}
  xm18 P001 N012 0 0 sky130_fd_pr__nfet_01v8 w={W_xm18} l={L_xm18}
.ends SUB_1

.control
  * DC Sweep to find operating point (mid-rail output)
  dc Vin 0.3 0.5 0.001
  meas dc vth_in when v(out)=0.9

  * Set Vin to the threshold for AC analysis
  alter Vin dc=$&vth_in ac=1

  * AC Analysis
  ac dec 100 1 1G
  let gain_db = vdb(out)
  let phase = 180/PI * cph(v(out))
  meas ac low_freq_gain find gain_db at=10
  meas ac unity_gain_freq when gain_db=0 fall=1
  meas ac f3db when gain_db='low_freq_gain - 3' fall=1
  meas ac phase_margin find phase when gain_db=0 fall=1

  * Transient Analysis for Slew Rate
  alter Vin dc=0 ac=0 pulse(0.2 0.6 1n 1n 1n 5u 10u)
  tran 10n 10u
  meas tran v_max max v(out)
  meas tran v_min min v(out)
  meas tran t_rise trig v(out) val=0.5 rise=1 targ v(out) val=1.5 rise=1
  meas tran t_fall trig v(out) val=1.5 fall=1 targ v(out) val=0.5 fall=1

  quit
.endc

